{
  "qid": "ISS0005-L3-01",
  "sample_id": "0005",
  "gen_prompt": "请画国际空间站经过地球背阳面时，假设其姿态控制系统故障，站体正在缓慢自旋，站体占据画面中心。",
  "invocation": "L3",
  "knowledge_dim": "航天器/空间站结构与世界知识",
  "fidelity_checks": [
    {
      "check": "站体在自旋中仍应表现为由多个相互连接的舱段组成的模块化组合体，而不是单一整体式飞船或散开部件。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "1"
        ],
        "derivation_chain": "前提：姿态控制系统故障导致站体缓慢自旋，但对象仍是国际空间站→知识[1]：国际空间站是由多个相互连接舱段组成的模块化航天设施组合体→视觉结论：自旋不改变模块化连接关系，站体应连续相连而非单一整体或散架。"
      },
      "rubric": {
        "tier_0": "画成单一整体式飞船，或舱段明显分离、断裂、彼此无连接。",
        "tier_1": "可见多个分段，但连接关系不清，或像松散堆叠，模块化组合体特征不完整。",
        "tier_2": "可见多个舱段通过节点或对接结构相互连接，形成连续完整的模块化组合体，且自旋未破坏其整体连接。"
      },
      "variants_used": "无",
      "visibility_requirement": "当站体主体可见面积不足以判断舱段连接时，本条最高只能给及格；若站体主体完全不可见，给0分。",
      "weight": 1.0
    },
    {
      "check": "站体应仍带有展开的大面积板状太阳能电池阵列；自旋只改变其朝向，不得使其消失或收拢成细条。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "2"
        ],
        "derivation_chain": "前提：站体缓慢自旋→知识[2]：国际空间站必须带有展开的大面积板状太阳能电池阵列→视觉结论：自旋中太阳翼仍应展开，仅因旋转呈现不同透视朝向，不得缺失或收拢。"
      },
      "rubric": {
        "tier_0": "没有太阳能电池阵列，或阵列完全收拢成细条/点状/装饰小块。",
        "tier_1": "可见板状结构，但面积不足、未完全展开，或被遮挡到难以判断为大型阵列。",
        "tier_2": "可见多块大面积板状太阳能电池阵列处于展开状态，并随自旋呈现合理的倾斜或透视朝向。"
      },
      "variants_used": "无",
      "visibility_requirement": "当太阳翼被站体部分遮挡时，只要可见部分足以判断其为展开板状阵列，可给及格或满分；若完全不可见，给0分。",
      "weight": 1.0
    },
    {
      "check": "站体应具有横向延伸的桁架式主梁结构，太阳能电池阵列或舱外设备应沿其安装；自旋可使主梁呈现透视倾斜，但不得缺失为无骨架的舱体堆叠。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "3"
        ],
        "derivation_chain": "前提：站体缓慢自旋→知识[3]：国际空间站具有横向延伸的桁架式主梁结构，作为太阳能电池阵列或设备的安装骨架→视觉结论：主梁仍应横向延伸并承载太阳翼或设备，自旋只改变观察角度。"
      },
      "rubric": {
        "tier_0": "没有横向桁架或主梁，站体像无骨架的舱体堆叠。",
        "tier_1": "可见梁状结构，但长度不足、不横向延伸，或看不出其作为太阳翼/设备安装骨架。",
        "tier_2": "可见横向延伸的桁架式主梁，太阳能电池阵列或舱外设备沿其布置，且自旋造成的透视倾斜合理。"
      },
      "variants_used": "无",
      "visibility_requirement": "当主梁被舱体遮挡时，可通过太阳翼或设备成排附着于一条主梁的可见关系判定；若该关系完全不可见，给0分。",
      "weight": 1.0
    },
    {
      "check": "空间站应悬浮于太空背景中，不得因经过地球背阳面而被画成停放在地面、发射台、天体表面，或在大气层云层中飞行。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "4"
        ],
        "derivation_chain": "前提：国际空间站经过地球背阳面→知识[4]：该光照现象发生在近地轨道外太空环境中→视觉结论：站体应悬浮于太空背景中，不得接触地面、发射台、天体表面，也不得表现为在云层中飞行。"
      },
      "rubric": {
        "tier_0": "空间站明显停在地面、发射台、天体表面，或像飞机一样在云层中飞行。",
        "tier_1": "有太空背景，但站体与地面、云层或天体表面存在接触、支撑、附着等不合法关系。",
        "tier_2": "空间站悬浮于太空背景中，无地面、发射台、天体表面支撑，也无云层中飞行的航空器状态。"
      },
      "variants_used": "无",
      "visibility_requirement": "当背景太空或地球不可见时，只要站体本身悬浮且无地面/云层接触线索，可给及格；若出现明确地面或云层接触，给0分。",
      "weight": 1.0
    },
    {
      "check": "站体及画面中不得出现机翼、尾翼、螺旋桨、喷气发动机等航空器空气动力学特征。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "5"
        ],
        "derivation_chain": "前提：画真实国际空间站→知识[5]：轨道航天器不需要航空器空气动力学控制面→视觉结论：不得出现机翼、尾翼、螺旋桨、喷气发动机等航空器空气动力学特征。"
      },
      "rubric": {
        "tier_0": "出现任一明确的机翼、尾翼、螺旋桨、喷气发动机或其他航空器空气动力学特征。",
        "tier_1": "存在易混淆的翼状或桨状结构，但整体仍可辨为天线、散热板、舱外设备等航天器部件。",
        "tier_2": "画面中无上述航空器空气动力学特征，所有突出结构均可合理归入航天器部件。"
      },
      "variants_used": "无",
      "visibility_requirement": "若局部不可见但可见部分无航空器特征，可给满分；只要可见部分出现明确航空器特征，给0分。",
      "weight": 1.0
    },
    {
      "check": "不得出现轮式起落架、轮胎、地面滑跑装置，或屋顶瓦片、烟囱、住宅门窗等地面建筑构件。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "6"
        ],
        "derivation_chain": "前提：国际空间站处于真实太空设施状态→知识[6]：其外观不应包含着陆轮组或地面建筑构件→视觉结论：不得出现轮式起落架、轮胎、地面滑跑装置及屋顶瓦片、烟囱、住宅门窗等地面建筑构件。"
      },
      "rubric": {
        "tier_0": "出现任一明确的轮式起落架、轮胎、地面滑跑装置，或屋顶瓦片、烟囱、住宅门窗等地面建筑构件。",
        "tier_1": "存在类似轮状、框状或管状结构，但可合理辨认为航天器天线、散热器、扶手、对接机构等设备。",
        "tier_2": "无上述轮式或地面建筑构件，所有结构均符合航天器舱外设备形态。"
      },
      "variants_used": "无",
      "visibility_requirement": "若局部不可见但可见部分无地面构件，可给满分；只要出现明确地面构件，给0分。",
      "weight": 1.0
    },
    {
      "check": "不得出现明确属于其他空间站的名称标识，如天宫、和平号/MIR。",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "7"
        ],
        "derivation_chain": "前提：概念对象为国际空间站→知识[7]：不得混淆为其他空间站→视觉结论：画面不得出现明确属于其他空间站的名称标识。"
      },
      "rubric": {
        "tier_0": "出现明确可识别的其他空间站名称标识，如天宫、和平号、MIR等。",
        "tier_1": "出现文字或标志但模糊不可识别，或为普通国旗、机构徽标，不指向其他空间站。",
        "tier_2": "无其他空间站名称标识，文字或标志均不造成站名混淆。"
      },
      "variants_used": "无",
      "visibility_requirement": "若标识完全不可见，本条按满分处理；若出现明确其他站名标识，给0分。",
      "weight": 1.0
    }
  ],
  "alignment_checks": [
    {
      "check": "题面点名的国际空间站是否作为画面主导主体。",
      "facet": "subject_prominence",
      "rubric": {
        "tier_0": "主体缺失、被其他物体主导，或无法识别为空间站组合体。",
        "tier_1": "空间站可见但占比偏小，视觉焦点不够明确。",
        "tier_2": "国际空间站占据画面主导地位，体量、位置和视觉焦点清晰。"
      }
    },
    {
      "check": "站体是否位于画面中心。",
      "facet": "spatial_2d",
      "rubric": {
        "tier_0": "站体明显不在画面中心。",
        "tier_1": "站体接近中心但明显偏移。",
        "tier_2": "站体位于画面中心区域。"
      }
    },
    {
      "check": "是否表现地球背阳面的环境状态。",
      "facet": "real_world_scene",
      "rubric": {
        "tier_0": "站体明显处于强烈太阳直射或白昼强光环境，与背阳面设定冲突。",
        "tier_1": "有阴影或低照度迹象，但仍保留较强太阳直射感。",
        "tier_2": "整体呈现地球背阳面带来的低照度、暗面或无直射光环境。"
      }
    },
    {
      "check": "站体是否呈现缓慢自旋的姿态。",
      "facet": "fullbody_action",
      "rubric": {
        "tier_0": "站体完全静态，无任何自旋或旋转暗示。",
        "tier_1": "站体有倾斜或非正常朝向，但自旋感较弱。",
        "tier_2": "站体呈现合理的自旋姿态，如多轴倾斜、朝向变化或透视扭转，不要求运动模糊。"
      }
    }
  ],
  "quality_facets": [
    "physical_logic",
    "material_texture",
    "edge_clarity",
    "noise"
  ],
  "aesthetic_facets": [
    "composition",
    "color_harmony",
    "lighting_atmosphere"
  ],
  "leak_check": {
    "对照表": [
      {
        "constraint_ref": "1",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "2",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "3",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "4",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "5",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "6",
        "题面中是否出现": "无"
      },
      {
        "constraint_ref": "7",
        "题面中是否出现": "无"
      }
    ],
    "结论": "全为无"
  },
  "notes": "样本图仅用于确认概念与场景形态；判分不要求金色太阳翼、航天飞机、United States字样或特定背景云图。题面只给L3前提，不泄露清单关键词。自旋检查不强制运动模糊，避免误杀合法静态画法。"
}
